#pragma once
struct MusicalKeyPicker:juce::Component{std::array<juce::TextButton,12> roots;juce::TextButton quality{"MAJ"},unknown{"UNKNOWN"},automatic{"USE DETECTED"},confirm{"APPLY"};bool minor=false;int root=0;std::function<void(MusicalKey)> apply;MusicalKeyPicker(){static const char* names[]{"C","C#","D","D#","E","F","F#","G","G#","A","A#","B"};setSize(238,196);for(int i=0;i<12;++i){addAndMakeVisible(roots[i]);roots[i].setButtonText(juce::String(names[i]));roots[i].setBounds(4+(i%4)*58,4+(i/4)*32,54,28);roots[i].onClick=[this,i]{root=i;for(int n=0;n<12;++n)roots[n].setToggleState(n==i,juce::dontSendNotification);};}for(auto* c:{&quality,&unknown,&automatic,&confirm})addAndMakeVisible(c);quality.setBounds(4,102,72,26);unknown.setBounds(80,102,154,26);automatic.setBounds(4,132,230,26);confirm.setBounds(4,164,230,26);confirm.onClick=[this]{if(apply)apply({root,minor?1:0});};quality.onClick=[this]{minor=!minor;quality.setButtonText(minor?"MIN":"MAJ");};unknown.onClick=[this]{if(apply)apply({-1,-1});};automatic.onClick=[this]{if(apply)apply({});};}};
